import { mkdir, readdir, readFile, unlink, writeFile } from 'node:fs/promises'
import path from 'node:path'
import type { GeneratedFile, WriteResult } from './types.js'

/** First line of every file the generator writes, which is how a later run recognizes its own files. */
export const GENERATED_HEADER = '// Generated by @vifrost/codegen'

/**
 * Writes the generated files into a directory and removes the files an earlier run generated
 * there that this run did not, such as those of models since excluded or deleted. Files without
 * the generated header are never touched.
 *
 * @param {string} outputDir the directory to write into, created if missing
 * @param {GeneratedFile[]} files the files of this run
 * @returns {Promise<WriteResult>} the names of the files written and removed
 */
export async function writeGeneratedFiles(outputDir: string, files: GeneratedFile[]): Promise<WriteResult> {
  await mkdir(outputDir, { recursive: true })

  for (const file of files) {
    await writeFile(path.join(outputDir, file.fileName), file.content, 'utf-8')
  }

  const written = files.map((file) => file.fileName)
  const writtenNames = new Set(written)
  const removed: string[] = []

  for (const entry of await readdir(outputDir, { withFileTypes: true })) {
    if (!entry.isFile() || !entry.name.endsWith('.ts') || writtenNames.has(entry.name)) {
      continue
    }
    const filePath = path.join(outputDir, entry.name)
    const content = await readFile(filePath, 'utf-8')
    if (content.startsWith(GENERATED_HEADER)) {
      await unlink(filePath)
      removed.push(entry.name)
    }
  }

  return { written, removed: removed.sort() }
}
